39	/// Cycle to the next collaboration mode preset in list order.
40	pub(crate) fn next_mask(
41	    model_catalog: &ModelCatalog,
42	    current: Option<&CollaborationModeMask>,
43	) -> Option<CollaborationModeMask> {
44	    let presets = filtered_presets(model_catalog);
45	    if presets.is_empty() {
46	        return None;
47	    }
48	    let current_kind = current.and_then(|mask| mask.mode);
49	    let next_index = presets
50	        .iter()
51	        .position(|mask| mask.mode == current_kind)
52	        .map_or(0, |idx| (idx + 1) % presets.len());
53	    presets.get(next_index).cloned()
54	}
