/// Set the model in the widget's config copy and stored collaboration mode.
    pub(crate) fn set_model(&mut self, model: impl Into<String>) {
        let model = model.into();
        self.current_collaboration_mode = self.current_collaboration_mode.with_updates(
            Some(model.clone()),
            /*effort*/ None,
            /*developer_instructions*/ None,
        );
        if self.collaboration_modes_enabled()
            && let Some(mask) = self.active_collaboration_mask.as_mut()
        {
            mask.model = Some(model);
        }
        self.refresh_model_display();
        // Keep the terminal title in sync so a model switch is reflected
        // immediately when the title is configured with the `model` token.
        self.refresh_terminal_title();
    }

    fn set_service_tier_selection(&mut self, service_tier: Option<ServiceTier>) {
            && let Some(effort) = self.config.plan_mode_reasoning_effort
        {
            mask.reasoning_effort = Some(Some(effort));
        }
        self.active_collaboration_mask = Some(mask);
        self.update_collaboration_mode_indicator();
        self.refresh_model_display();
        // Reflect the new mode's reasoning effort in the footer status line
        // immediately, without requiring a separate refresh call.
        self.refresh_status_line();
        let next_mode = self.active_mode_kind();

